import java.util.*;

public class CountGoodEdge {

    public static int countGoodEdge(int n, int k, int[] values, int[][] edges) {
        // Create the adjacency list for the tree
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 1; i <= n; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // Function to perform DFS and count the frequency of values in a subtree
        Map<Integer, Integer> dfs(int node, int parent) {
            Map<Integer, Integer> subtreeCount = new HashMap<>();
            Stack<int[]> stack = new Stack<>();
            stack.push(new int[]{node, parent});

            while (!stack.isEmpty()) {
                int[] current = stack.pop();
                int currentNode = current[0];
                int currentParent = current[1];
                subtreeCount.put(values[currentNode - 1], subtreeCount.getOrDefault(values[currentNode - 1], 0) + 1);

                for (int neighbor : graph.get(currentNode)) {
                    if (neighbor != currentParent) {
                        stack.push(new int[]{neighbor, currentNode});
                    }
                }
            }

            return subtreeCount;
        }

        // Function to check if the subtree satisfies the given condition
        boolean isGoodSubtree(Map<Integer, Integer> subtreeCount) {
            for (int count : subtreeCount.values()) {
                if (count > k) {
                    return false;
                }
            }
            return true;
        }

        int goodEdgesCount = 0;

        // Iterate over each edge and check if it's a good edge
        for (int[] edge : edges) {
            Map<Integer, Integer> subtreeU = dfs(edge[0], edge[1]);
            Map<Integer, Integer> subtreeV = dfs(edge[1], edge[0]);

            if (isGoodSubtree(subtreeU) && isGoodSubtree(subtreeV)) {
                goodEdgesCount += 1;
            }
        }

        return goodEdgesCount;
    }

    // Example usage
    public static void main(String[] args) {
        int n = 4;
        int k = 2;
        int[] values = {1, 1, 1, 1};
        int[][] edges = {{1, 2}, {1, 3}, {1, 4}};

        System.out.println(countGoodEdge(n, k, values, edges));  // Output should be 3
    }
}
```

### Explanation:

1. **Graph Construction:** The graph is represented using an adjacency list with a `HashMap` where each node has a list of its adjacent nodes.
2. **DFS Function:** The `dfs` method traverses the tree using a stack (iterative DFS) to count the frequency of values in the subtree rooted at a given node.
3. **Subtree Validation:** The `isGoodSubtree` method checks if the frequencies of values in a subtree are within the allowed limit \( k \).
4. **Edge Iteration:** The main method iterates over each edge, simulates its removal by calculating the frequency of values in the resulting subtrees using the `dfs` method, and checks if both subtrees meet the criteria using `isGoodSubtree`.
5. **Count Good Edges:** If both subtrees meet the criteria, it increments the count of good edges.

This Java implementation follows the same logic as the Python solution, ensuring that we correctly identify and count all good edges in the tree based on the given constraints.

