```javascript
import { useState, useEffect } from 'react';
import { navLinks } from '../constants/index.js';

const NavItems = ({ onClick = () => {} }) => (
  <ul className="nav-ul">
    {navLinks.map((item) => (
      <li key={item.id} className="nav-li">
        <a href={item.href} className="nav-li_a text-white" onClick={onClick}>
          {item.name}
        </a>
      </li>
    ))}
  </ul>
);

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  const toggleMenu = () => setIsOpen(!isOpen);
  const closeMenu = () => setIsOpen(false);

  // Detect scroll to toggle navbar styles
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 0) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 mt-4 ${
        scrolled ? 'rounded-none' : 'rounded-full'
      } transition-all ease-in-out`}
    >
      <div className="max-w-7xl mx-auto">
        <div
          className={`flex justify-between items-center py-4 px-6 mx-auto bg-ultramarine-blue shadow-lg ${
            scrolled ? 'pl-4 pr-8' : ''
          } transition-all ease-in-out`}
        >
          <a
            href="/"
            className="font-bold text-xl text-white hover:text-gray-200 transition-colors"
          >
            <img
              src="/assets/infrasnaplogo.png" // Updated to logo image path
              alt="InfraSnap Logo"
              className={`h-12 transition-all ease-in-out ${
                scrolled ? 'transform translate-x-4' : ''
              }`}
            />
          </a>

          <button
            onClick={toggleMenu}
            className="hover:text-gray-200 focus:outline-none sm:hidden flex"
            aria-label="Toggle menu"
          >
            <img
              src={isOpen ? 'assets/close.svg' : 'assets/menu.svg'}
              alt="toggle"
              className="w-6 h-6"
            />
          </button>

          <nav className="sm:flex hidden">
            <NavItems />
          </nav>
        </div>
      </div>

      <div
        className={`nav-sidebar ${isOpen ? 'max-h-screen' : 'max-h-0'} rounded-b-lg bg-ultramarine-blue text-white shadow-md`}
      >
        <nav className="p-5">
          <NavItems onClick={closeMenu} />
        </nav>
      </div>
    </header>
  );
};

export default Navbar;
```

### Key Changes:
1. **Scroll Detection**: The `useEffect` hook tracks scroll events and updates the `scrolled` state to toggle between rounded and full navbar (`rounded-none`).
2. **Logo Transition**: The logo now shifts slightly to the right (`transform translate-x-4`) when scrolled down.
3. **Navbar Transition**: Adjusted the navbar padding and other styles dynamically when the page is scrolled.

This will ensure that the navbar becomes a full rectangle when you scroll down, and the logo and nav links smoothly move according to the scroll.

