```js
import express from 'express';
import axios from 'axios';
import User from '../models/User.js';
import dotenv from 'dotenv';
import { getGeminiIntent } from '../utils/geminiIntent.js'; // we'll make this file next

dotenv.config();
const router = express.Router();
const TMDB_API_KEY = process.env.TMDB_API_KEY;

router.post('/:username', async (req, res) => {
  try {
    const { username } = req.params;
    const { query } = req.body;

    // 1. Fetch user
    const user = await User.findOne({ username });
    if (!user) return res.status(404).json({ message: 'User not found' });

    // 2. Ask Gemini to interpret user query
    const geminiData = await getGeminiIntent(query);

    // 3. Fallbacks
    const genres = geminiData.genres || ['Action', 'Comedy'];
    const count = geminiData.count || 5;

    // 4. Get TMDb genre IDs
    const genreRes = await axios.get(`https://api.themoviedb.org/3/genre/movie/list?api_key=${TMDB_API_KEY}`);
    const genreMap = genreRes.data.genres.reduce((acc, g) => {
      acc[g.name.toLowerCase()] = g.id;
      return acc;
    }, {});

    const genreIds = genres.map(g => genreMap[g.toLowerCase()]).filter(Boolean);
    if (!genreIds.length) {
      return res.status(400).json({ message: 'No valid genres matched' });
    }

    // 5. Fetch movies
    const tmdbRes = await axios.get(`https://api.themoviedb.org/3/discover/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        with_genres: genreIds.join(','),
        sort_by: 'popularity.desc',
        page: 1
      }
    });

    const results = tmdbRes.data.results || [];

    // 6. Filter by watchlist/history
    const watchedIds = new Set([...user.watchlist, ...user.history].map(m => m.id));
    const freshMovies = results.filter(movie => !watchedIds.has(movie.id)).slice(0, count);

    res.json({ recommendations: freshMovies, from: 'smart route' });

  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error', error: err.message });
  }
});

export default router;
```

