public class Solution {

    public int maximumSkill2(int s, int n, int d, int[][] problems) {
        // Sort the problems based on their ratings
        Arrays.sort(problems, (a, b) -> Integer.compare(a[0], b[0]));

        int currentSkills = s;
        int days = 0;

