import dotenv from 'dotenv';
import { GoogleGenerativeAI } from '@google/generative-ai';

dotenv.config();

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY);

export async function getGeminiIntent(query) {
  try {
    const model = genAI.getGenerativeModel({ model: 'gemini-pro' });

    const prompt = `
You are a movie recommendation assistant. Given a user query, extract only the following details in JSON:
- genres: a list of movie genres (like Action, Comedy, Drama, etc.)
- count: number of movies the user wants (default 5 if not specified)

Respond in this exact JSON format:
{ "genres": [...], "count": number }

User query: "${query}"
    `;

    const result = await model.generateContent(prompt);
    const response = result.response.text();

    // Try to parse response as JSON
    const match = response.match(/{[\s\S]*}/);
    if (match) {
      return JSON.parse(match[0]);
    } else {
      console.warn('Could not parse Gemini response:', response);
      return {};
    }

  } catch (err) {
    console.error('Gemini error:', err.message);
    return {};
  }
}
