void insertTerm(Node*& head, int coeff, int exp) {
    Node* newNode = new Node{coeff, exp, nullptr};
    if (head == nullptr) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }
        current->next = newNode;
