        if (current1->exponent > current2->exponent) {
            insertTerm(result, current1->coefficient, current1->exponent);
            current1 = current1->next;
        } else if (current1->exponent < current2->exponent) {
            insertTerm(result, current2->coefficient, current2->exponent);
            current2 = current2->next;
        } else {
            // Coefficients have the same exponent, add them
            int sumCoeff = current1->coefficient + current2->coefficient;
            insertTerm(result, sumCoeff, current1->exponent);
            current1 = current1->next;
            current2 = current2->next;
        }
    }

    // Add any remaining terms from poly1
    while (current1 != nullptr) {
        insertTerm(result, current1->coefficient, current1->exponent);
        current1 = current1->next;
    }

    // Add any remaining terms from poly2
    while (current2 != nullptr) {
        insertTerm(result, current2->coefficient, current2->exponent);
        current2 = current2->next;
    }

    return result;
}

// Function to display a polynomial represented as a linked list
void displayPolynomial(Node* poly) {
    Node* current = poly;
    while (current != nullptr) {
        std::cout << current->coefficient << "x^" << current->exponent;
        current = current->next;
        if (current != nullptr) {
            std::cout << " + ";
        }
    }
    std::cout << std::endl;
}

// Example usage
