    Node* poly1 = nullptr;
    Node* poly2 = nullptr;

    // Insert terms into poly1
    insertTerm(poly1, 3, 2);
    insertTerm(poly1, 5, 1);
    insertTerm(poly1, 2, 0);

    // Insert terms into poly2
